import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.BvlN9b-o.js";const E=JSON.parse('{"title":"API 配置","description":"","frontmatter":{},"headers":[],"relativePath":"reference/config.md","filePath":"reference/config.md"}'),c={name:"reference/config.md"};function n(a,t,i,s,_,l){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="api-配置" tabindex="-1">API 配置 <a class="header-anchor" href="#api-配置" aria-label="Permalink to &quot;API 配置&quot;">​</a></h1><p>从 Settings 定义自动生成；生产秘密不进入文档。</p><table tabindex="0"><thead><tr><th>变量</th><th>默认值</th><th>敏感值</th><th>说明</th></tr></thead><tbody><tr><td><code>DATABASE_URL</code></td><td>必填</td><td>是</td><td>PostgreSQL connection URL. Required; never logged.</td></tr><tr><td><code>APP_BIND</code></td><td>127.0.0.1:3000</td><td>否</td><td>API listener IP address and port.</td></tr><tr><td><code>RUST_LOG</code></td><td>info</td><td>否</td><td>Structured log filter.</td></tr><tr><td><code>MIGRATION_TIMEOUT_SECS</code></td><td>30</td><td>否</td><td>Migration execution deadline in seconds (1..3600).</td></tr><tr><td><code>APP_ORIGIN</code></td><td><a href="http://127.0.0.1:5173" target="_blank" rel="noreferrer">http://127.0.0.1:5173</a></td><td>否</td><td>Trusted browser origin. HTTPS required except loopback development.</td></tr><tr><td><code>SESSION_ABSOLUTE_SECS</code></td><td>604800</td><td>否</td><td>Absolute session lifetime in seconds (60..2592000).</td></tr><tr><td><code>SESSION_IDLE_SECS</code></td><td>86400</td><td>否</td><td>Idle session lifetime in seconds (60..absolute lifetime).</td></tr><tr><td><code>S3_ENDPOINT</code></td><td>必填</td><td>否</td><td>Internal S3 endpoint at its root path. Unset disables object storage.</td></tr><tr><td><code>S3_PUBLIC_ENDPOINT</code></td><td>必填</td><td>否</td><td>Browser-accessible S3 origin. Defaults to S3_ENDPOINT; HTTPS except loopback.</td></tr><tr><td><code>S3_BUCKET</code></td><td>saas-files</td><td>否</td><td>Dedicated private application bucket.</td></tr><tr><td><code>S3_REGION</code></td><td>us-east-1</td><td>否</td><td>S3 signing region.</td></tr><tr><td><code>S3_ACCESS_KEY</code></td><td>必填</td><td>是</td><td>Explicit S3 access key; required when S3_ENDPOINT is set.</td></tr><tr><td><code>S3_SECRET_KEY</code></td><td>必填</td><td>是</td><td>Explicit S3 secret; required when enabled, never logged.</td></tr><tr><td><code>FILE_MAX_BYTES</code></td><td>20971520</td><td>否</td><td>File byte limit, verified again on the final object (1..104857600).</td></tr><tr><td><code>UPLOAD_SESSION_SECS</code></td><td>900</td><td>否</td><td>Upload resource/signing lifetime in seconds (1..3600).</td></tr><tr><td><code>DOWNLOAD_URL_SECS</code></td><td>60</td><td>否</td><td>Download capability lifetime in seconds (1..300). Revocation blocks new signing.</td></tr><tr><td><code>WORKER_BIND</code></td><td>127.0.0.1:3001</td><td>否</td><td>Worker health listener IP address and port.</td></tr><tr><td><code>JOB_LEASE_SECS</code></td><td>60</td><td>否</td><td>Job lease lifetime (5..3600 seconds).</td></tr><tr><td><code>JOB_HEARTBEAT_SECS</code></td><td>20</td><td>否</td><td>Lease renewal interval (1..half the lease seconds).</td></tr><tr><td><code>JOB_SHUTDOWN_SECS</code></td><td>10</td><td>否</td><td>Maximum active-work drain before process exit (1..60 seconds).</td></tr><tr><td><code>JOB_MAINTENANCE_SECS</code></td><td>30</td><td>否</td><td>Interval for bounded maintenance scheduling (1..3600 seconds).</td></tr><tr><td><code>EXPORT_JOB_MAX_ATTEMPTS</code></td><td>5</td><td>否</td><td>Finite attempt budget per export execution batch (1..20).</td></tr><tr><td><code>EXPORT_MAX_ATTACHMENTS</code></td><td>100</td><td>否</td><td>Maximum attachments in one document export (0..1000).</td></tr><tr><td><code>EXPORT_MAX_INPUT_BYTES</code></td><td>268435456</td><td>否</td><td>Maximum snapshot Markdown and attachment bytes (1..1073741824).</td></tr><tr><td><code>EXPORT_MAX_OUTPUT_BYTES</code></td><td>285212672</td><td>否</td><td>Maximum ZIP extent, including headers and central directory (1024..1107296256).</td></tr><tr><td><code>EXPORT_RETENTION_SECS</code></td><td>86400</td><td>否</td><td>Export and snapshot lifetime (60..604800 seconds).</td></tr><tr><td><code>EXPORT_TIMEOUT_SECS</code></td><td>120</td><td>否</td><td>Entire export execution budget (1..600 seconds), with cooperative blocking cancellation.</td></tr></tbody></table><p>开发脚本额外读取的 PostgreSQL 端口、Web 代理和教程 URL 见 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/edbd56eba3fbbe51bc6e7ef4287fe3cffe17d7c2/.env.example" target="_blank" rel="noreferrer">.env.example</a>；它们不是浏览器可读取的 DATABASE_URL。</p>',4)])])}const T=d(c,[["render",n]]);export{E as __pageData,T as default};
